INSERT INTO `projects` VALUES ('31f678de-28ed-4f1e-9d44-ba68c1a61138','tenant-default-001','Hospital Administration System','The Enhanced Patient Management System (EPMS) project aims to modernize and streamline the patient management processes within healthcare networks. By integrating advanced technologies and optimizing existing workflows, the project seeks to improve patient care, enhance operational efficiency, and ensure compliance with regulatory standards.','in_progress','high','2026-01-15 00:00:00.000','2026-11-15 00:00:00.000',1400.00,45,'EcoVision Enterprises','2026-09-30 04:20:20.782','2026-09-30 04:27:43.484',NULL,'[{\"id\": \"file-1790742463483\", \"name\": \"EPMS_HIPAA_Compliance_Matrix_2026.pdf\", \"size\": \"2.4 MB\", \"type\": \"pdf\", \"uploadedAt\": \"2026-09-30T04:27:43.483Z\", \"uploadedBy\": \"admin@masterhrms.com\"}]','[{\"id\": \"note-1790742367172\", \"date\": \"Sep 30, 2026\", \"title\": \"Sprint 4 Telemedicine Gateway Review\", \"author\": \"admin@masterhrms.com\", \"content\": \"Validated WebRTC signaling tokens and automated failover to STUN/TURN relays with zero downtime.\"}]'),('b17b4a6d-1d45-46f6-b09a-6357b583e2af','s40_alpha_1790622747871','Enterprise Architecture Upgrade',NULL,'in_progress','medium',NULL,NULL,50000.00,0,'Acme Industrial Corp','2026-09-28 19:12:27.945','2026-09-28 19:12:27.945',NULL,NULL,NULL);
